import wave, numpy as np
with wave.open('/tmp/fx_test.wav', 'rb') as w:
    audio = np.frombuffer(w.readframes(w.getnframes()), dtype=np.int16).reshape(-1, 2)[:, 0].astype(float)

def est_freq(seg):
    zc = np.where(np.diff(np.signbit(seg)))[0]
    if len(zc) < 4: return 0
    return 44100.0 / (2.0 * np.mean(np.diff(zc)))

for r in [0, 2, 3, 4]:
    print(f"Row {r} end freq:", round(est_freq(audio[r*5292+3500 : (r+1)*5292]), 2))
for tick in range(6):
    s0 = 6*5292 + tick*882 + 100
    print(f"Row 6 arp tick {tick} freq:", round(est_freq(audio[s0:s0+700]), 2))
EOF"}

